input.code:
const dsl = `workspace "Library" "A small public library system." {
    model {
        patron = person "Patron" "Borrows books at the library."
        library = softwareSystem "Library" "Manages books and loans." {
            catalog = container "Catalog Web App" "Lets patrons browse the catalogue." "Python"
            circulation = container "Circulation Service" "Records loans and returns." "Java"
        }
        patron -> catalog "Browses the catalogue through" "HTTPS"
        catalog -> circulation "Records loans via" "gRPC"
    }
    views {
        systemContext library "SystemContext" {
            include *
            autoLayout
        }
    }
}`;

const c4 = await tools.structurizr["export-c4plantuml"]({ dsl, viewKey: "SystemContext" });
const puml = c4.definition;

const esc = s => String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");

const titleM = puml.match(/title <size:24>([^<]+)<\/size>/);
const title = titleM ? titleM[1] : "C4 View";

const COLORS = {
  Person:"#0E7C7B", Person_Ext:"#666666", System:"#1168BD", System_Ext:"#999999",
  System_Queue:"#B3B3B3", Container:"#43C6AC", Database:"#0E907E", Theme:"#36495A",
  Agent:"#5C7AEA", Node:"#828282"
};
const STEREOTYPES = {
  Person:"Person", Person_Ext:"Person", System:"Software System", System_Ext:"Software System",
  System_Queue:"Queue", Container:"Container", Database:"Database", Theme:"Theme", Agent:"Agent", Node:"Node"
};

const elements = [];
const elemRe = /^\s*(Person_Ext|Person|System_Ext|System_Queue|System|Container|Database|Theme|Agent|Node)\((\w+),\s*"([^"]*)",\s*\$descr="([^"]*)"/gm;
let m;
while ((m = elemRe.exec(puml)) !== null) {
  elements.push({ type: m[1], id: m[2], name: m[3], descr: m[4] });
}

const rels = [];
const relRe = /^\s*(BiRel|Rel_Ext|Rel_Ui|Rel)\((\w+),\s*(\w+),\s*"([^"]*)"(?:,\s*\$techn="([^"]*)")?/gm;
while ((m = relRe.exec(puml)) !== null) {
  rels.push({ kind: m[1], from: m[2], to: m[3], label: m[4], techn: m[5] || "" });
}

// Column layout: longest path from a source (left to right)
const col = {};
elements.forEach(e => col[e.id] = 0);
for (let i = 0; i < elements.length; i++) {
  let changed = false;
  rels.forEach(r => {
    if (col[r.from] !== undefined && col[r.to] !== undefined && col[r.to] < col[r.from] + 1) {
      col[r.to] = col[r.from] + 1; changed = true;
    }
  });
  if (!changed) break;
}

const boxW = 210, boxH = 120, gapX = 200, gapY = 70, margin = 40, contentTop = 100;
const nCols = Math.max(...elements.map(e => col[e.id])) + 1;
const cols = Array.from({ length: nCols }, () => []);
elements.forEach(e => cols[col[e.id]].push(e));
const colHeights = cols.map(c => c.length * boxH + (c.length - 1) * gapY);
const totalContentH = Math.max(...colHeights);
const pos = {};
cols.forEach((c, ci) => {
  const x = margin + ci * (boxW + gapX);
  const y0 = contentTop + (totalContentH - colHeights[ci]) / 2;
  c.forEach((e, i) => { pos[e.id] = { x, y: y0 + i * (boxH + gapY) }; });
});
const W = margin * 2 + nCols * boxW + (nCols - 1) * gapX;

const legendTypes = [...new Set(elements.map(e => e.type))];
const legendY = contentTop + totalContentH + 40;
const legendH = 80;
const H = legendY + legendH + 30;

function icon(type, x, y) {
  const w = "white";
  switch (type) {
    case "Person":
    case "Person_Ext":
      return `<circle cx="${x+30}" cy="${y+30}" r="8" fill="${w}"/>` +
        `<path d="M ${x+17} ${y+58} Q ${x+17} ${y+42} ${x+30} ${y+42} Q ${x+43} ${y+42} ${x+43} ${y+58} Z" fill="${w}"/>`;
    case "System":
    case "System_Ext":
      return `<rect x="${x+14}" y="${y+22}" width="32" height="22" rx="2" fill="${w}"/>` +
        `<line x1="${x+30}" y1="${y+44}" x2="${x+30}" y2="${y+52}" stroke="${w}" stroke-width="3"/>` +
        `<line x1="${x+20}" y1="${y+52}" x2="${x+40}" y2="${y+52}" stroke="${w}" stroke-width="3"/>`;
    case "Container":
      return `<polygon points="${x+30},${y+18} ${x+46},${y+26} ${x+30},${y+34} ${x+14},${y+26}" fill="${w}"/>` +
        `<polygon points="${x+14},${y+26} ${x+30},${y+34} ${x+30},${y+52} ${x+14},${y+44}" fill="${w}" opacity="0.85"/>` +
        `<polygon points="${x+46},${y+26} ${x+30},${y+34} ${x+30},${y+52} ${x+46},${y+44}" fill="${w}" opacity="0.7"/>`;
    case "Database":
      return `<path d="M ${x+16} ${y+24} L ${x+16} ${y+50} A 14 6 0 0 0 ${x+44} ${y+50} L ${x+44} ${y+24} Z" fill="${w}"/>` +
        `<ellipse cx="${x+30}" cy="${y+24}" rx="14" ry="6" fill="${w}"/>`;
    default:
      return `<rect x="${x+16}" y="${y+24}" width="28" height="28" rx="4" fill="${w}"/>`;
  }
}

function wrap(text, maxChars) {
  const words = String(text).split(" ");
  const lines = [];
  let cur = "";
  for (const w of words) {
    if ((cur + " " + w).trim().length > maxChars && cur) { lines.push(cur); cur = w; }
    else cur = (cur + " " + w).trim();
  }
  if (cur) lines.push(cur);
  return lines;
}

let svg = `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" font-family="Helvetica, Arial, sans-serif">
<defs>
<marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
<path d="M 0 0 L 10 5 L 0 10 z" fill="#444444"/>
</marker>
</defs>
<rect width="${W}" height="${H}" fill="#ffffff"/>
<text x="${W/2}" y="52" text-anchor="middle" font-size="24" fill="#444444">${esc(title)}</text>
`;

for (const e of elements) {
  const p = pos[e.id];
  const color = COLORS[e.type] || "#36495A";
  const lines = wrap(e.descr, 26);
  let descText = "";
  lines.forEach((ln, i) => {
    descText += `<text x="${p.x+58}" y="${p.y+74+i*15}" font-size="12" fill="white">${esc(ln)}</text>\n`;
  });
  svg += `<g>
<rect x="${p.x}" y="${p.y}" width="${boxW}" height="${boxH}" rx="8" fill="${color}"/>
${icon(e.type, p.x, p.y)}
<text x="${p.x+58}" y="${p.y+38}" font-size="16" font-weight="bold" fill="white">${esc(e.name)}</text>
<text x="${p.x+58}" y="${p.y+56}" font-size="12" fill="white">[${esc(STEREOTYPES[e.type] || e.type)}]</text>
${descText}</g>
`;
}

for (const r of rels) {
  const a = pos[r.from], b = pos[r.to];
  if (!a || !b) continue;
  let x1, y1, x2, y2;
